package com.example.internmanagement.controller;
import com.example.internmanagement.util.DBConnection; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*;
@WebServlet({"/admin/users","/admin/permissions"})
public class AdminServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{try(Connection c=DBConnection.getConnection()){if(q.getServletPath().endsWith("users")){List<Map<String,String>> rows=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT u.id,u.username,u.full_name,u.email,u.status,COALESCE(r.role_code,'UNASSIGNED') role_code FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id ORDER BY u.id DESC");ResultSet r=p.executeQuery()){while(r.next()){Map<String,String>x=new HashMap<>();for(String k:List.of("id","username","full_name","email","status","role_code"))x.put(k,r.getString(k));rows.add(x);}}q.setAttribute("users",rows);q.getRequestDispatcher("/WEB-INF/views/screens/ui-40-user-manage.jsp").forward(q,s);}else{q.setAttribute("roles",roles(c));q.setAttribute("permissions",permissions(c));q.getRequestDispatcher("/WEB-INF/views/screens/ui-41-rbac.jsp").forward(q,s);}}catch(SQLException e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{q.setCharacterEncoding("UTF-8");try(Connection c=DBConnection.getConnection()){if(q.getServletPath().endsWith("users")){c.setAutoCommit(false);int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO users(username,password,email,full_name,status,create_at,update_at,c_password) VALUES(?,?,?,?, 'ACTIVE',CURDATE(),CURDATE(),false)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,q.getParameter("username"));p.setString(2,q.getParameter("password"));p.setString(3,q.getParameter("email"));p.setString(4,q.getParameter("fullName"));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE role_code=?")){p.setInt(1,id);p.setString(2,q.getParameter("role"));p.executeUpdate();}c.commit();s.sendRedirect(q.getContextPath()+"/admin/users?created=1");}else{String role=q.getParameter("role");String[] grants=q.getParameterValues("permission");try(PreparedStatement p=c.prepareStatement("DELETE rp FROM role_permissions rp JOIN roles r ON r.id=rp.role_id WHERE r.role_code=?")){p.setString(1,role);p.executeUpdate();}if(grants!=null)try(PreparedStatement p=c.prepareStatement("INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r,permissions p WHERE r.role_code=? AND p.permission_code=?")){for(String grant:grants){p.setString(1,role);p.setString(2,grant);p.addBatch();}p.executeBatch();}s.sendRedirect(q.getContextPath()+"/admin/permissions?updated=1");}}catch(SQLException e){throw new ServletException("Không thể lưu cấu hình quản trị",e);}}
 private List<String> roles(Connection c)throws SQLException{return column(c,"SELECT role_code FROM roles ORDER BY role_code","role_code");} private List<String> permissions(Connection c)throws SQLException{return column(c,"SELECT permission_code FROM permissions ORDER BY permission_code","permission_code");} private List<String> column(Connection c,String sql,String col)throws SQLException{List<String>a=new ArrayList<>();try(PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){while(r.next())a.add(r.getString(col));}return a;}
}
